import{c as e,Q as d,j as a,m as c}from"./chunks/framework.CWBTDBPu.js";const p=JSON.parse('{"title":"YuChat 权限节点","description":"","frontmatter":{"title":"YuChat 权限节点"},"headers":[],"relativePath":"plugins/items/yu-chat/permissions.md","filePath":"plugins/items/yu-chat/permissions.md"}'),o={name:"plugins/items/yu-chat/permissions.md"};function r(s,t,h,i,n,u){return d(),a("div",null,[...t[0]||(t[0]=[c(`<h1 id="yuchat-权限节点" tabindex="-1">YuChat 权限节点 <a class="header-anchor" href="#yuchat-权限节点" aria-label="Permalink to &quot;YuChat 权限节点&quot;">​</a></h1><p>YuChat 使用 Bukkit 权限系统，可直接交给 LuckPerms、GroupManager、PermissionsEx 等权限插件管理。</p><h2 id="基础权限" tabindex="-1">基础权限 <a class="header-anchor" href="#基础权限" aria-label="Permalink to &quot;基础权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuchat.use</code></td><td>true</td><td>使用 YuChat 基础功能，包含打开主 GUI 和重置显示设置。</td></tr><tr><td><code>yuchat.gui</code></td><td>true</td><td>打开 YuChat 主 GUI。</td></tr><tr><td><code>yuchat.nickname.use</code></td><td>true</td><td>修改昵称。</td></tr><tr><td><code>yuchat.signature.use</code></td><td>true</td><td>设置个性签名。</td></tr><tr><td><code>yuchat.deathmessage.use</code></td><td>true</td><td>设置自定义死亡消息。</td></tr></tbody></table><h2 id="限制绕过" tabindex="-1">限制绕过 <a class="header-anchor" href="#限制绕过" aria-label="Permalink to &quot;限制绕过&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuchat.signature.bypass</code></td><td>op</td><td>绕过个性签名长度限制。</td></tr><tr><td><code>yuchat.deathmessage.bypass</code></td><td>op</td><td>绕过自定义死亡消息长度限制。</td></tr><tr><td><code>yuchat.nickname.input-color</code></td><td>配置控制</td><td>允许昵称输入携带颜色。</td></tr><tr><td><code>yuchat.nickname.change</code></td><td>配置控制</td><td>允许变更昵称。</td></tr></tbody></table><h2 id="聊天颜色与格式" tabindex="-1">聊天颜色与格式 <a class="header-anchor" href="#聊天颜色与格式" aria-label="Permalink to &quot;聊天颜色与格式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuchat.chat.color</code></td><td>op</td><td>允许聊天内容使用 <code>&amp;</code> / <code>§</code> legacy 颜色码。</td></tr><tr><td><code>yuchat.chat.minimessage</code></td><td>op</td><td>允许聊天内容使用 MiniMessage 风格标签。</td></tr><tr><td><code>yuchat.chat.hex</code></td><td>op</td><td>允许聊天内容使用 Hex 颜色。</td></tr><tr><td><code>yuchat.chat.placeholder</code></td><td>op</td><td>允许聊天内容解析 PlaceholderAPI。</td></tr><tr><td><code>yuchat.message.color.*</code></td><td>op</td><td>消息颜色总权限，可按服务器配置拆分到具体颜色。</td></tr><tr><td><code>yuchat.format.*</code></td><td>配置控制</td><td>昵称或文本格式总权限，例如粗体、斜体、下划线等。</td></tr></tbody></table><h2 id="称呼与效果" tabindex="-1">称呼与效果 <a class="header-anchor" href="#称呼与效果" aria-label="Permalink to &quot;称呼与效果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>yuchat.title.&lt;id&gt;</code></td><td>拥有某个称呼。默认示例包含 <code>yuchat.title.vip</code>、<code>yuchat.title.helper</code>。</td></tr><tr><td><code>yuchat.title.*</code></td><td>拥有全部称呼，适合管理员或测试组。</td></tr><tr><td><code>yuchat.effect.&lt;id&gt;</code></td><td>拥有某个颜色或动态效果。</td></tr><tr><td><code>yuchat.effect.*</code></td><td>拥有全部效果。</td></tr></tbody></table><p>称呼也可以通过购买或管理员授权获得；来自权限节点的称呼通常视为永久拥有。若使用 LuckPerms 临时权限，权限过期后 YuChat 会在过期检查中取消对应激活状态。</p><h2 id="管理权限" tabindex="-1">管理权限 <a class="header-anchor" href="#管理权限" aria-label="Permalink to &quot;管理权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuchat.admin</code></td><td>op</td><td>打开管理员 GUI，创建称呼和编辑管理配置。</td></tr><tr><td><code>yuchat.reload</code></td><td>op</td><td>执行 <code>/yc reload</code>。</td></tr></tbody></table><h2 id="推荐权限组" tabindex="-1">推荐权限组 <a class="header-anchor" href="#推荐权限组" aria-label="Permalink to &quot;推荐权限组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组</th><th>建议权限</th></tr></thead><tbody><tr><td>普通玩家</td><td><code>yuchat.use</code>、<code>yuchat.gui</code>、<code>yuchat.nickname.use</code>、<code>yuchat.signature.use</code>、<code>yuchat.deathmessage.use</code></td></tr><tr><td>会员玩家</td><td>普通玩家权限，加 <code>yuchat.chat.color</code>、部分 <code>yuchat.title.&lt;id&gt;</code>、部分 <code>yuchat.effect.&lt;id&gt;</code></td></tr><tr><td>管理员</td><td><code>yuchat.admin</code>、<code>yuchat.reload</code>、<code>yuchat.title.*</code>、<code>yuchat.effect.*</code>、颜色与格式权限</td></tr></tbody></table><h2 id="luckperms-示例" tabindex="-1">LuckPerms 示例 <a class="header-anchor" href="#luckperms-示例" aria-label="Permalink to &quot;LuckPerms 示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp group default permission set yuchat.use true</span></span>
<span class="line"><span>/lp group default permission set yuchat.gui true</span></span>
<span class="line"><span>/lp group default permission set yuchat.nickname.use true</span></span>
<span class="line"><span>/lp group vip permission set yuchat.title.vip true</span></span>
<span class="line"><span>/lp group vip permission set yuchat.effect.rainbow true</span></span>
<span class="line"><span>/lp group admin permission set yuchat.admin true</span></span>
<span class="line"><span>/lp group admin permission set yuchat.reload true</span></span></code></pre></div>`,17)])])}const y=e(o,[["render",r]]);export{p as __pageData,y as default};
